import type * as PrismNamespace from 'prismjs';
import includeLanguages from '@theme-original/prism-include-languages';
import grammar from '@site/data/modelspec.grammar.json';

// The `modelspec` fence language. The word lists are generated by `modelspec-docs` from the
// lexer, the operator registry and the parser; only the token shapes are written here.

const words = (list: string[]) => new RegExp(`\\b(?:${list.join('|')})\\b`);

export default function prismIncludeLanguages(Prism: typeof PrismNamespace): void {
  includeLanguages(Prism);
  Prism.languages.modelspec = {
    comment: {pattern: /\/\/.*/, greedy: true},
    keyword: words(grammar.keywords),
    builtin: words(grammar.builtins),
    'class-name': [words(grammar.types), /\b[A-Z][A-Za-z0-9_]*\b/],
    function: /\b[a-z_][A-Za-z0-9_]*(?=\s*\()/,
    property: {
      pattern: /(^[ \t]*|[(,][ \t]*)[a-z_][A-Za-z0-9_]*(?=[ \t]*=)/m,
      lookbehind: true,
    },
    number: /\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b/,
    operator: /->|[=+\-*/%^]/,
    punctuation: /[{}()[\]<>:;,.]/,
  };
  Prism.languages.mspec = Prism.languages.modelspec;
}
